const rows = $json.results || $json.data || [];

let context = {};
try {
  context = $("Build Logistics Query").first().json;
} catch (e) {
  context = {};
}

const logisticsItems = rows.map((row) => ({ ...row }));

return [
  {
    json: {
      agent: "logistics_specialist",
      domain: "Logistics Specialist",
      status: "data_retrieved",
      question: context.question || "",
      evidenceLabel: "logisticsItems",
      evidenceData: logisticsItems,
      generatedCypher: context.query || "",
      params: context.params || {},
      queryDebug: context.queryDebug || {},
      rawResult: $json,
    },
  },
];

const agent = $json.agent || "logistics_specialist";
const domain = $json.domain || "Logistics Specialist";
const question = $json.question || "";
const evidenceData = $json.evidenceData || [];
const rawResult = $json.rawResult || {};
const generatedCypher = $json.generatedCypher || "";
const queryDebug = $json.queryDebug || {};
const dbSchema = rawResult.schema || "";

let sourceChunks = [];
try {
  sourceChunks = $("When Executed by Another Workflow").first().json.sourceChunks || [];
} catch (e) {}

const contextStr = sourceChunks.length > 0
  ? "\n\nRetrieved Unstructured Document Context:\n" + sourceChunks.map(c => "--- File: " + (c.documentName || c.filename) + " ---\n" + c.text).join("\n\n")
  : "";

const systemPrompt = `
You are a Logistics Specialist Agent for a supply chain knowledge graph.

Active Database Schema:
${dbSchema || "No active schema available."}

Rules:
- Use the provided graph query results and any retrieved unstructured document context.
- Do not invent countries, sites, station counts, or station IDs.
- Charging station counts must be based on unique physical units.
- The Cypher already uses count(DISTINCT cs.unit_id), so use station_count exactly as provided.
- If multiple rows have the same highest station_count, report it as a tie.
- If country values are ISO country codes like DE, AT, ES, FR, IT, mention the code. You may optionally include the common country name if obvious.
- Do not add risk analysis unless the user asks about risk.
- Return ONLY valid JSON.
`;

const userPrompt = `
User question:
${question}

Query debug:
${JSON.stringify(queryDebug, null, 2)}

Generated Cypher:
${generatedCypher}

Logistics evidence:
${JSON.stringify(evidenceData, null, 2)}

Raw graph result:
${JSON.stringify(rawResult, null, 2)}${contextStr}

Return JSON with this exact schema:
{
  "answer": "string",
  "keyFindings": ["string"],
  "logisticsInsights": [
    {
      "id": "string",
      "type": "string",
      "name": "string",
      "insight": "string"
    }
  ],
  "routeInsights": [
    {
      "route": "string",
      "impact": "string"
    }
  ],
  "recommendations": ["string"],
  "confidence": "low | medium | high"
}
`;

return [
  {
    json: {
      agent,
      domain,
      question,
      evidenceData,
      generatedCypher,
      queryDebug,
      llmPayload: {
        model: "google/gemma-4-31B-it",
        messages: [
          {
            role: "system",
            content: systemPrompt,
          },
          {
            role: "user",
            content: userPrompt,
          },
        ],
        temperature: 0.1,
        max_tokens: 2048,
      },
    },
  },
];

let outputStr = "";

if ($json.choices?.[0]?.message?.content) {
  outputStr = $json.choices[0].message.content;
} else if ($json.text) {
  outputStr = $json.text;
} else if ($json.response) {
  outputStr = $json.response;
} else {
  outputStr = JSON.stringify($json);
}

outputStr = outputStr
  .replace(/<think>[\s\S]*?<\/think>/gi, "")
  .replace(/^\s*```json/i, "")
  .replace(/^\s*```/i, "")
  .replace(/```\s*$/i, "")
  .trim();

let parsed;

try {
  parsed = JSON.parse(outputStr);
} catch (e) {
  parsed = {
    answer: outputStr || "The logistics specialist could not generate a summary.",
    keyFindings: [],
    logisticsInsights: [],
    routeInsights: [],
    recommendations: [],
    confidence: "low",
  };
}

let context = {};
try {
  context = $("Build LLM Summary Payload").first().json;
} catch (e) {
  context = {};
}

return [
  {
    json: {
      agent: "logistics_specialist",
      domain: "Logistics Specialist",
      status: "completed",
      question: context.question || "",
      answer: parsed.answer || "",
      keyFindings: parsed.keyFindings || [],
      logisticsInsights: parsed.logisticsInsights || [],
      routeInsights: parsed.routeInsights || [],
      recommendations: parsed.recommendations || [],
      confidence: parsed.confidence || "medium",
      evidence: {
        logisticsItems: context.evidenceData || [],
      },
      generatedCypher: context.generatedCypher || "",
      queryDebug: context.queryDebug || {},
      rawLlmOutput: parsed,
    },
  },
];

let selectedAgents = $json.selectedAgents || [];

if (typeof selectedAgents === "string") {
  try {
    selectedAgents = JSON.parse(selectedAgents);
  } catch (e) {
    selectedAgents = selectedAgents
      .split(",")
      .map((agent) => agent.trim())
      .filter(Boolean);
  }
}

if (!Array.isArray(selectedAgents)) {
  selectedAgents = [];
}

const shouldRun =
  selectedAgents.includes("logistics_specialist") ||
  selectedAgents.includes("all");

return [
  {
    json: {
      ...$json,
      selectedAgents,
      shouldRun,
    },
  },
];

return [
  {
    json: {
      agent: "logistics_specialist",
      domain: "Logistics Specialist",
      status: "skipped",
      question: $json.question || "",
      answer: "",
      keyFindings: [],
      logisticsInsights: [],
      routeInsights: [],
      recommendations: [],
      confidence: "not_applicable",
      evidence: {},
    },
  },
];
